package com.dentalcrm.dashboard;
import com.dentalcrm.appointment.*; import com.dentalcrm.patient.PatientRepository; import com.dentalcrm.payment.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.List; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class DashboardServiceTest {@Test void separatesQrRevenue(){var patients=mock(PatientRepository.class);var appts=mock(AppointmentRepository.class);var payments=mock(PaymentRepository.class);when(patients.count()).thenReturn(3L);when(appts.findByStartTimeBetweenOrderByStartTime(any(),any())).thenReturn(List.of());Payment qr=new Payment();qr.setAmount(new BigDecimal("1200.00"));qr.setPaymentMethod(PaymentMethod.QR);Payment cash=new Payment();cash.setAmount(new BigDecimal("500.00"));cash.setPaymentMethod(PaymentMethod.CASH);when(payments.findByPaidAtBetween(any(),any())).thenReturn(List.of(qr,cash));var result=new DashboardService(patients,appts,payments).summary(OffsetDateTime.now(),OffsetDateTime.now().plusDays(1));assertEquals(new BigDecimal("1200.00"),result.qrRevenue());assertEquals(new BigDecimal("1700.00"),result.clinicRevenue());}}
